#include "model.h"
#include <stdio.h>
#include <assert.h>
// 支位の確認😀：利用者の名前と表示用の文字列は保持する。
int main(void) {
    struct Item items[] = {{1,2},{2,3}};
    int 日本語 = 7;
    Value total = compute(items, sizeof(items)/sizeof(items[0]), identity);
    assert(sizeof(Value)>0);
    printf("支位😀 %s %d\n", TEXT(JOIN(sample,_name)), 日本語);
    if(total < 0) return 1;
    return 0;
}

#ifndef APP_MODEL_H
#define APP_MODEL_H
#include <stddef.h>
#include <stdbool.h>
#if defined(USE_DOUBLE)
typedef double Value;
#else
typedef int Value;
#endif
struct Item { int code; Value value; };
typedef Value (*Transform)(Value);
Value compute(const struct Item *items, size_t count, Transform action);
Value identity(Value printf);
_Static_assert(sizeof(Value) >= sizeof(int), "Value width");
#define JOIN_INNER(a,b) a ## b
#define JOIN(a,b) JOIN_INNER(a,b)
#define TEXT_INNER(x) #x
#define TEXT(x) TEXT_INNER(x)
#define CREATE_SLOT(name,type,value) type JOIN(name,_slot) = (value)
#define EMPTY
#define GO(name) goto JOIN(name,_end)
#endif

#include "model.h"
#include <stdatomic.h>
#include <complex.h>
#include <math.h>
#include <assert.h>
static atomic_uint calls;
Value identity(Value printf) { return printf; }
Value compute(const struct Item *items, size_t count, Transform action) {
    Value total = 0;
    CREATE_SLOT(work,Value,0);
    {
#define SLOT_TYPE int
#define SLOT_INITIAL 1
#include "slot.h"
        work_slot += scratch;
#undef SLOT_TYPE
#undef SLOT_INITIAL
    }
    {
#define SLOT_TYPE Value
#define SLOT_INITIAL 2
#include "slot.h"
        work_slot += scratch;
#undef SLOT_TYPE
#undef SLOT_INITIAL
    }
    for(size_t i=0; i<count; ++i) total += action(items[i].value);
    for(EMPTY;EMPTY;EMPTY) break;
    double complex z = CMPLX(1,2);
    work_slot += (Value)creal(z);
    atomic_fetch_add_explicit(&calls,1,memory_order_relaxed);
    assert(sizeof(Value)>0);
#if defined(USE_DOUBLE)
    total += (Value)0.5;
#else
    total += 1;
#endif
    if(total<0) GO(finish);
    work_slot = 0;
finish_end:
    return total + work_slot;
}

